UPDATE public.exercise_pool SET primary_muscles=ARRAY['Quadríceps','Glúteo Máximo','Adutores']::text[], instructions=E'1. Sente-se no aparelho e posicione os pés na plataforma na largura dos ombros.\n2. Destrave a trava de segurança e segure os apoios laterais para estabilizar o tronco.\n3. Flexione os joelhos e quadris de forma controlada, descendo a plataforma até que suas coxas fiquem próximas ao peito, sem perder o contato da lombar com o banco.\n4. Empurre a plataforma de volta à posição inicial, aplicando força através do meio do pé e calcanhares.\n5. Pare o movimento pouco antes da extensão total dos joelhos para manter a tensão muscular.', common_mistakes=E'- Bloqueio completo (hiperextensão) dos joelhos no topo do movimento.\n- Tirar a região lombar ou o glúteo do encosto durante a descida.\n- Valgo dinâmico (deixar os joelhos colapsarem para dentro).\n- Tirar os calcanhares da plataforma, concentrando o peso na ponta dos pés.' WHERE id='63a7a6b1-317a-46e2-a4c1-cc7659083ab6';
